INSERT INTO vocabulary_entries
  (id, word, ipa, pos, level, meaning_ru, definition_en, example, collocations, source, source_url, status, version, reviewed_at)
VALUES
('voc-1', 'Substantiate', '/səbˈstæn.ʃi.eɪt/', 'verb', 'C1', 'Обосновывать, подкреплять доказательствами', 'To provide evidence to support or prove the truth of an assertion.', 'The candidate failed to substantiate her central claim with empirical research.', '["substantiate claims", "substantiate findings", "substantiate an argument"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-2', 'Corroborate', '/kəˈrɒb.ə.reɪt/', 'verb', 'C1', 'Подтверждать, свидетельствовать в пользу', 'To confirm or give support to a statement, theory, or finding.', 'Recent atmospheric observations corroborate the predictions of climate modeling.', '["corroborate evidence", "corroborate a hypothesis", "strongly corroborate"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-3', 'Paradigm', '/ˈpær.ə.daɪm/', 'noun', 'C1', 'Парадигма, образец, концептуальная модель', 'A typical example or pattern of something; a model or overarching framework.', 'The shift toward renewable energy represents a fundamental paradigm shift in economics.', '["paradigm shift", "dominant paradigm", "scientific paradigm"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-4', 'Empirical', '/ɪmˈpɪr.ɪ.kəl/', 'adjective', 'C1', 'Эмпирический, основанный на опыте и фактах', 'Based on, concerned with, or verifiable by observation rather than theory alone.', 'The author provides extensive empirical data to validate the sociolinguistic hypothesis.', '["empirical evidence", "empirical study", "empirical research"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-5', 'Delineate', '/dɪˈlɪn.i.eɪt/', 'verb', 'C1', 'Очерчивать, четко описывать, разграничивать', 'To describe, portray, or outline with precision and detail.', 'The initial chapter delineates the boundaries between micro- and macroeconomics.', '["delineate clearly", "delineate boundaries", "delineate responsibilities"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-6', 'Mitigate', '/ˈmɪt.ɪ.ɡeɪt/', 'verb', 'B2', 'Смягчать, уменьшать тяжесть или вред', 'To make less severe, serious, or painful; to alleviate.', 'Urban reforestation policies help mitigate the heat island effect in metropolitan areas.', '["mitigate risks", "mitigate impact", "mitigate circumstances"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-7', 'Exacerbate', '/ɪɡˈzæs.ə.beɪt/', 'verb', 'C1', 'Обострять, усугублять, ухудшать', 'To make a problem, bad situation, or negative feeling worse.', 'Delaying necessary structural reforms will only exacerbate fiscal instability.', '["exacerbate the problem", "exacerbate tensions", "exacerbate poverty"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-8', 'Ubiquitous', '/juːˈbɪk.wɪ.təs/', 'adjective', 'C1', 'Вездесущий, повсеместно распространенный', 'Present, appearing, or found everywhere simultaneously.', 'Mobile telecommunications have become ubiquitous across emerging global economies.', '["ubiquitous presence", "ubiquitous technology", "ubiquitous nature"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-9', 'Pragmatic', '/præɡˈmæt.ɪk/', 'adjective', 'B2', 'Прагматичный, ориентированный на практическую пользу', 'Dealing with things sensibly and realistically in a way that is based on practical rather than theoretical considerations.', 'The committee adopted a pragmatic approach to budget allocation under strict austerity.', '["pragmatic solution", "pragmatic approach", "pragmatic decision"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-10', 'Juxtapose', '/ˌdʒʌk.stəˈpəʊz/', 'verb', 'C1', 'Сопоставлять, помещать рядом для сравнения', 'To place or deal with close together for contrasting effect.', 'The essay juxtaposes traditional pedagogical philosophies with modern algorithmic learning.', '["juxtapose against", "juxtaposed with", "strikingly juxtapose"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-11', 'Ephemeral', '/ɪˈfem.ər.əl/', 'adjective', 'C2', 'Мимолетный, недолговечный, эфемерный', 'Lasting for a very short time; transient.', 'Online social media trends often exert an ephemeral influence on public consensus.', '["ephemeral nature", "ephemeral phenomenon", "ephemeral pleasures"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-12', 'Unprecedented', '/ʌnˈpres.ɪ.den.tɪd/', 'adjective', 'C1', 'Беспрецедентный, не имеющий аналогов в прошлом', 'Never done or known before; without previous example.', 'The past decade witnessed an unprecedented expansion of synthetic intelligence systems.', '["unprecedented scale", "unprecedented growth", "unprecedented challenge"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-13', 'Coherent', '/kəʊˈhɪə.rənt/', 'adjective', 'B2', 'Связный, логичный, последовательный', 'Logical, consistent, and easily understood as a whole.', 'The candidate was commended for presenting a remarkably coherent argumentative structure.', '["coherent argument", "coherent narrative", "coherent policy"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-14', 'Intrinsic', '/ɪnˈtrɪn.zɪk/', 'adjective', 'C1', 'Внутренний, присущий, неотъемлемый', 'Belonging naturally; essential; inherent.', 'Curiosity and autonomy are intrinsic drivers of sustained intellectual achievement.', '["intrinsic value", "intrinsic motivation", "intrinsic property"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-15', 'Elucidate', '/iˈluː.sɪ.deɪt/', 'verb', 'C1', 'Проливать свет, разъяснять, делать понятным', 'To make something clear; explain thoroughly.', 'The lecturer utilized statistical charts to elucidate the complexities of macro inflation.', '["elucidate the mechanism", "elucidate points", "further elucidate"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-16', 'Disparity', '/dɪˈspær.ə.ti/', 'noun', 'C1', 'Неравенство, несоответствие, разрыв', 'A great difference or inequality, typically in an unfair manner.', 'Significant income disparity persists between metropolitan and peripheral rural districts.', '["economic disparity", "growing disparity", "racial disparity"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-17', 'Synthesize', '/ˈsɪn.θə.saɪz/', 'verb', 'C1', 'Синтезировать, обобщать и объединять разнородное', 'To combine a number of things into a coherent whole.', 'In the conclusion, students must synthesize secondary literature into a novel perspective.', '["synthesize data", "synthesize information", "synthesize findings"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-18', 'Plausible', '/ˈplɔː.zə.bəl/', 'adjective', 'B2', 'Правдоподобный, убедительный, вероятный', 'Seeming reasonable, probable, or worthy of belief.', 'The experimental results provide a plausible explanation for the genetic mutation.', '["plausible explanation", "plausible scenario", "highly plausible"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-19', 'Advocate', '/ˈæd.və.keɪt/', 'verb', 'B2', 'Выступать в защиту, отстаивать, пропагандировать', 'To publicly recommend or support a particular cause or policy.', 'Leading economists advocate substantial investment in sustainable public transit.', '["strongly advocate", "advocate reforms", "advocate for change"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-20', 'Inherent', '/ɪnˈher.ənt/', 'adjective', 'C1', 'Неотъемлемый, прирожденный, свойственный', 'Existing in something as a permanent, essential, or characteristic attribute.', 'Every scientific measurement carries an inherent degree of margin error.', '["inherent risk", "inherent flaw", "inherent contradiction"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-21', 'Albeit', '/ɔːlˈbiː.ɪt/', 'conjunction', 'C1', 'Хотя, тем не менее', 'Though; even though.', 'He accepted the job, albeit with some hesitation.', '["albeit briefly", "albeit slow", "albeit imperfect"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-22', 'Ameliorate', '/əˈmiːl.jə.reɪt/', 'verb', 'C2', 'Улучшать, облегчать', 'To make something bad or unsatisfactory better.', 'New policies aim to ameliorate living conditions in impoverished districts.', '["ameliorate conditions", "ameliorate symptoms", "ameliorate poverty"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-23', 'Anachronism', '/əˈnæk.rə.nɪ.zəm/', 'noun', 'C2', 'Анахронизм, пережиток', 'A thing belonging or appropriate to a period other than that in which it exists.', 'Using floppy disks today is a technological anachronism.', '["historical anachronism", "cultural anachronism", "seem an anachronism"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-24', 'Anomaly', '/əˈnɒm.ə.li/', 'noun', 'C1', 'Аномалия, отклонение', 'Something that deviates from what is standard, normal, or expected.', 'The data showed a statistical anomaly in temperature recordings.', '["statistical anomaly", "detect an anomaly", "genetic anomaly"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-25', 'Antithesis', '/ænˈtɪθ.ə.sɪs/', 'verb', 'C2', 'Антитеза, полная противоположность', 'A person or thing that is the direct opposite of someone or something else.', 'His reckless behavior is the exact antithesis of his philosophy.', '["exact antithesis", "direct antithesis", "antithesis of democracy"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-26', 'Apprehensive', '/ˌæp.rɪˈhen.sɪv/', 'adjective', 'C1', 'Опасающийся, тревожный', 'Anxious or fearful that something bad or unpleasant will happen.', 'Students felt apprehensive about the adaptive testing format.', '["apprehensive about", "feel apprehensive", "apprehensive expression"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-27', 'Arbitrary', '/ˈɑː.bɪ.trər.i/', 'adjective', 'C1', 'Произвольный, случайный', 'Based on random choice or personal whim, rather than reason or system.', 'The decision appeared completely arbitrary without empirical backing.', '["arbitrary decision", "arbitrary rule", "seem arbitrary"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-28', 'Articulate', '/ɑːˈtɪk.jə.leɪt/', 'verb', 'C1', 'Четко формулировать, излагать', 'Express an idea or feeling fluently and coherently in words.', 'She was able to articulate complex economic theories concisely.', '["articulate ideas", "articulate clearly", "highly articulate"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-29', 'Ascertain', '/ˌæs.əˈteɪn/', 'verb', 'C1', 'Устанавливать, выяснять', 'Find something out for certain; make sure of.', 'Further trials are required to ascertain the drug efficacy.', '["ascertain the truth", "ascertain the cause", "ascertain facts"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-30', 'Assimilate', '/əˈsɪm.ɪ.leɪt/', 'verb', 'C1', 'Усваивать, ассимилировать', 'Take in and fully understand information or ideas; absorb into a culture.', 'Immigrants were encouraged to assimilate into the broader community.', '["assimilate knowledge", "assimilate culture", "assimilate rapidly"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-31', 'Augment', '/ɔːɡˈment/', 'verb', 'C1', 'Увеличивать, дополнять', 'Make something greater by adding to it; increase.', 'The university augmented its endowment with private grants.', '["augment income", "augment capabilities", "augment resources"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
