('voc-33', 'Belligerent', '/bəˈlɪdʒ.ər.ənt/', 'adjective', 'C2', 'Воинственный, агрессивный', 'Hostile and aggressive; engaged in war or conflict.', 'His belligerent posture alienated prospective diplomatic allies.', '["belligerent tone", "belligerent nation", "belligerent attitude"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-34', 'Benevolent', '/bəˈnev.əl.ənt/', 'adjective', 'C1', 'Великодушный, благожелательный', 'Well meaning and kindly; charitable.', 'A benevolent donor funded the construction of the STEM facility.', '["benevolent donor", "benevolent foundation", "benevolent ruler"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-35', 'Brevity', '/ˈbrev.ə.ti/', 'noun', 'C1', 'Краткость, лаконичность', 'Concise and exact use of words in writing or speech.', 'Brevity is essential when composing 5-minute timed exam responses.', '["brevity of expression", "for the sake of brevity", "admirable brevity"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-36', 'Capitulate', '/kəˈpɪtʃ.ə.leɪt/', 'verb', 'C2', 'Капитулировать, уступать', 'Cease to resist an opponent or an unwelcome demand; surrender.', 'The administration refused to capitulate to pressure from lobbyists.', '["capitulate to demands", "refuse to capitulate", "eventually capitulate"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-37', 'Catalyst', '/ˈkæt.əl.ɪst/', 'noun', 'C1', 'Катализатор, стимул', 'A person or thing that precipitates an event or change.', 'Technological disruption acted as a catalyst for educational reform.', '["catalyst for change", "economic catalyst", "serve as a catalyst"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
