('voc-41', 'Commensurate', '/kəˈmen.sjər.ət/', 'adjective', 'C2', 'Соразмерный, соответствующий', 'Corresponding in size, extent, or degree; proportionate.', 'Remuneration will be commensurate with qualifications and experience.', '["commensurate with experience", "commensurate reward", "commensurate scale"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-42', 'Compelling', '/kəmˈpel.ɪŋ/', 'adjective', 'C1', 'Убедительный, захватывающий', 'Evoking interest, attention, or admiration in a powerfully irresistible way.', 'The researcher presented compelling empirical data to justify her conclusion.', '["compelling evidence", "compelling argument", "compelling rationale"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-43', 'Comprehensive', '/ˌkɒm.prɪˈhen.sɪv/', 'adjective', 'C1', 'Всесторонний, исчерпывающий', 'Complete; including all or nearly all elements or aspects of something.', 'The academy provides a comprehensive syllabus for the Duolingo exam.', '["comprehensive analysis", "comprehensive review", "comprehensive study"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-44', 'Concede', '/kənˈsiːd/', 'verb', 'C1', 'Уступать, признавать', 'Admit that something is true or valid after first denying it.', 'The debater had to concede that the counterargument possessed merit.', '["concede defeat", "concede a point", "concede that"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-45', 'Concur', '/kənˈkɜːr/', 'verb', 'C1', 'Соглашаться, совпадать', 'Be of the same opinion; agree.', 'Leading epidemiologists concur with the updated vaccine guidelines.', '["concur with the verdict", "fully concur", "experts concur"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-46', 'Condone', '/kənˈdəʊn/', 'verb', 'C2', 'Потворствовать, оправдывать', 'Accept and allow behavior that is considered morally wrong to continue.', 'The university does not condone academic plagiarism under any circumstance.', '["condone violence", "refuse to condone", "condone misconduct"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-47', 'Conducive', '/kənˈdʒuː.sɪv/', 'adjective', 'C2', 'Способствующий, благоприятный', 'Making a certain situation or outcome likely or possible.', 'A quiet study environment is highly conducive to rigorous concentration.', '["conducive to learning", "conducive to success", "conducive atmosphere"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-48', 'Conjecture', '/kənˈdʒek.tʃər/', 'noun', 'C2', 'Догадка, предположение', 'An opinion or conclusion formed on the basis of incomplete information.', 'Without documentary evidence, theories remain mere historical conjecture.', '["pure conjecture", "matter of conjecture", "scientific conjecture"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-49', 'Conscientious', '/ˌkɒn.ʃiˈen.ʃəs/', 'adjective', 'C1', 'Добросовестный, сознательный', 'Wishing to do what is right, especially to do one''s work or duty well.', 'Conscientious students consistently review difficult C-Test words.', '["conscientious worker", "conscientious effort", "conscientious student"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-50', 'Consensus', '/kənˈsen.səs/', 'noun', 'C1', 'Консенсус, общее согласие', 'A general agreement reached by a group.', 'A broad scientific consensus exists regarding anthropogenic warming.', '["reach consensus", "general consensus", "scientific consensus"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
