('voc-52', 'Contemplate', '/ˈkɒn.təm.pleɪt/', 'verb', 'C1', 'Обдумывать, созерцать', 'Look thoughtfully at or think profoundly about something.', 'Scholars contemplate the long-term implications of synthetic intelligence.', '["contemplate the future", "contemplate options", "contemplate a career"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
('voc-53', 'Contention', '/kənˈten.ʃən/', 'noun', 'C2', 'Утверждение, предмет спора', 'An assertion, especially one maintained in argument; heated disagreement.', 'It is my contention that adaptive algorithms produce fairer testing outcomes.', '["bone of contention", "central contention", "point of contention"]'::jsonb, 'Academic Word List (platform dataset)', 'https://www.wgtn.ac.nz/lals/resources/academicwordlist', 'published', '2026.1', NOW()),
